package kz.zani.mobile

import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import kz.zani.mobile.core.*
import kz.zani.mobile.data.*
import kz.zani.mobile.ui.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

@OptIn(ExperimentalCoroutinesApi::class)
class TaskClientEditTest {
    private fun fixture(name:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$name.json")!!.bufferedReader().use {it.readText()}
    private fun catalog()=JSONObject(fixture("task-client-partial-cases"))
    private fun detail(b:Int=101,id:Int=1101)=JsonContracts.taskDetails(fixture("task-$b-$id"))
    private val context=TaskCommentContext(101,1101,1)
    private fun source(revision:Int=1,epoch:Int=1,original:TaskClientOriginal=detail().clientRead)=TaskClientEditSource(TaskCommentRead(TaskCommentContext(101,1101,epoch),revision),detail().task,original)
    private fun choice()=TaskDraftClientChoice.make(profile(),101,1754)!!
    private fun draft(mode:TaskClientEditMode)=TaskClientEditDraft(mode,choice(),source().read,"  ")
    private class Port(update:Boolean=true):SyntheticTaskClientEditPort {
        override val grants=listOf(SyntheticTaskClientEditGrant(101,1101,9001,update),SyntheticTaskClientEditGrant(202,1201,9002,update));val calls=mutableListOf<TaskClientEditAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticTaskClientEditOutcome>>()
        override suspend fun execute(attempt:TaskClientEditAttempt):SyntheticTaskClientEditOutcome {calls+=attempt;return CompletableDeferred<SyntheticTaskClientEditOutcome>().also {pending+=it}.await()}
    }
    private fun page()=JsonContracts.clients(FixtureClientSearch.list(fixture("client-search-catalogue-101"),101,"").body)
    private fun profile()=JsonContracts.clientProfile(FixtureClientSearch.profile(fixture("client-search-catalogue-101"),101,1754).body)
    private class Reads:ClientSearchRepository {
        val lists=mutableListOf<CompletableDeferred<ClientList>>();val details=mutableListOf<CompletableDeferred<ClientProfile>>()
        override suspend fun searchClients(business:Int,search:String)=CompletableDeferred<ClientList>().also {lists+=it}.await()
        override suspend fun clientProfile(business:Int,id:Int)=CompletableDeferred<ClientProfile>().also {details+=it}.await()
    }
    private inner class Repo:TaskReadRepository,ClientSearchRepository {
        override suspend fun tasks(business:Int)=JsonContracts.tasks(fixture("tasks-$business"))
        override suspend fun taskDetails(business:Int,id:Int)=detail(business,id)
        override suspend fun searchClients(business:Int,search:String)=JsonContracts.clients(FixtureClientSearch.list(fixture("client-search-catalogue-$business"),business,search).body)
        override suspend fun clientProfile(business:Int,id:Int)=if(id==1754)profile() else JsonContracts.clientProfile(fixture("client-$business-$id"))
    }
    private fun check(block:suspend TestScope.(TaskClientEditModel,Port,Reads)->Unit)=runTest {val p=Port();val r=Reads();val m=TaskClientEditModel(p,this,r);m.bind(source());try {block(m,p,r)}finally {m.bind(null)}}
    private fun TestScope.list(m:TaskClientEditModel,r:Reads) {m.open(m.control);m.choose(TaskClientEditMode.SET,m.control);m.updateQuery("  ",m.inputControl);m.readClients(m.control,m.picker.control);runCurrent();r.lists.last().complete(page());runCurrent()}
    private fun TestScope.select(m:TaskClientEditModel,r:Reads) {list(m,r);m.openClient(1754,m.control,m.picker.control);runCurrent();r.details.last().complete(profile());runCurrent();m.useClient(m.control,m.picker.control)}
    @Test fun strictOriginalProjectionUsesExactExistingGetFieldAndKeepsUnknownDistinctFromNull() {val rows=catalog().getJSONArray("original_cases");for(i in 0 until rows.length()){val row=rows.getJSONObject(i);val expected=when(row.getString("kind")){"client"->TaskClientOriginal.Client(row.getInt("id"));"notSet"->TaskClientOriginal.NotSet;else->TaskClientOriginal.Unknown};assertEquals(row.getString("name"),expected,TaskClientOriginal.decode(row.getString("payload_json")));val parsed=runCatching {JsonContracts.taskDetails(row.getString("payload_json"))}.getOrNull();if(parsed!=null)assertEquals(expected,parsed.clientRead)}}
    @Test fun oneFieldSetNullAndSeparateUpdateGrantDoNotSerializeAnyOtherTaskField() {val s=source();assertNull(TaskClientEditDraft().change(s));val auth=SyntheticTaskClientEditGrant(101,1101,9001,true).authorization(context)!!;assertNull(SyntheticTaskClientEditGrant(101,1101,9001,false).authorization(context));for(mode in TaskClientEditMode.entries){val review=TaskClientEditReview(s,1,draft(mode));val a=TaskClientEditLedger().begin(review,auth)!!;val body=JSONObject(a.preparedBody()!!);assertEquals(setOf("client"),body.keys().asSequence().toSet());if(mode==TaskClientEditMode.CLEAR)assertTrue(body.isNull("client"))else assertEquals(1754,body.getInt("client"));assertEquals(review.draft,a.review.draft)}}
    @Test fun unknownOriginalOldReadForeignChoiceAndUnchosenQueryCannotCreateReview() {val d=draft(TaskClientEditMode.SET);assertNull(d.copy(choice=null).change(source()));assertNull(d.copy(choiceRead=TaskCommentRead(context,2)).change(source()));assertNull(d.copy(choice=TaskDraftClientChoice.make(JsonContracts.clientProfile(fixture("client-202-801")),202,801)).change(source()));assertNull(d.change(source(original=TaskClientOriginal.Unknown)));assertNull(draft(TaskClientEditMode.CLEAR).change(source(original=TaskClientOriginal.Unknown)));for(status in listOf("open","in_progress","done","cancelled","future-status")){val s=source().copy(task=detail().task.copy(status=status));assertEquals(status in setOf("open","in_progress"),s.valid)}}
    @Test fun sharedSelectedGenericFkAndExactTaskBusinessStatusTimestampOutcomeMustMatch() {val rows=catalog().getJSONArray("result_cases");val auth=SyntheticTaskClientEditGrant(101,1101,9001,true).authorization(context)!!;for(i in 0 until rows.length()){val row=rows.getJSONObject(i);val mode=if(row.getString("mode")=="clear")TaskClientEditMode.CLEAR else TaskClientEditMode.SET;val r=TaskClientEditReview(source(),1,draft(mode));val ledger=TaskClientEditLedger();val a=ledger.begin(r,auth)!!;val body=a.preparedBody();assertNull(ledger.begin(r,auth));assertFalse(ledger.acknowledge(auth));ledger.complete(a,SyntheticTaskClientEditOutcome.Response(row.getInt("status"),row.getString("response_json")));val record=ledger.visible(auth)!!;assertEquals(row.getString("name"),row.getBoolean("accepted"),record.phase==TaskClientEditPhase.CONFIRMED);assertEquals(body,record.attempt.preparedBody());assertEquals(r,record.attempt.review);if(!row.getBoolean("accepted")){assertFalse(ledger.acknowledge(auth));assertTrue(ledger.blocked(TaskCommentContext(101,1101,2)));assertNull(ledger.visible(SyntheticTaskClientEditGrant(101,1101,9001,true).authorization(TaskCommentContext(101,1101,2))));assertNull(ledger.begin(r,auth))}}}
    @Test fun openingHasNoModeCandidateDateOrAutomaticGetAndOldModeInputCannotOverwrite()=check {m,_,r->assertTrue(m.canOpen);m.open(m.control);m.prepare(m.control);assertNull(m.review);assertTrue(m.showsIssue);assertNull(m.draft.mode);assertTrue(m.draft.query.isEmpty());assertTrue(r.lists.isEmpty());m.choose(TaskClientEditMode.SET,m.control);val input=m.inputControl;val child=m.picker.control;m.updateQuery("  ",input);m.choose(TaskClientEditMode.CLEAR,m.control);val saved=m.draft;m.updateQuery("overwrite",input);assertEquals(saved,m.draft)}
    @Test fun closeQuarantinesLateListAndReopenRetainsOnlyExplicitRawQuery()=check {m,_,r->m.open(m.control);m.choose(TaskClientEditMode.SET,m.control);m.updateQuery("  ",m.inputControl);m.readClients(m.control,m.picker.control);runCurrent();val saved=m.draft;m.back(m.control);val closed=m.control;r.lists.last().complete(page());runCurrent();assertEquals(closed,m.control);assertEquals(saved,m.draft);assertNull(m.picker.state.context);m.open(m.control);assertEquals("  ",m.picker.state.query);assertFalse(m.picker.state.loaded)}
    @Test fun currentWindowAndCompletedIndependentDetailRequiredBeforeSelection()=check {m,_,r->list(m,r);m.openClient(999999,m.control,m.picker.control);assertNull(m.picker.state.profileSelection);m.openClient(1754,m.control,m.picker.control);runCurrent();val pending=m.picker.control;m.useClient(m.control,pending);assertNull(m.draft.choice);r.details.last().complete(profile());runCurrent();m.useClient(m.control,pending);assertNull(m.draft.choice);m.useClient(m.control,m.picker.control);assertEquals(1754,m.draft.choice!!.id);assertEquals(source().read,m.draft.choiceRead)}
    @Test fun foreignThenExplicitRetryDoesNotDefaultOrMutateOriginalTask()=check {m,_,r->val original=m.source;list(m,r);m.openClient(1754,m.control,m.picker.control);runCurrent();r.details.last().complete(JsonContracts.clientProfile(fixture("client-202-801")));runCurrent();assertEquals(ReadProblem.INVALID_PAYLOAD,m.picker.profile.state.problem);assertNull(m.draft.choice);m.retryClient(m.control,m.picker.control);runCurrent();r.details.last().complete(profile());runCurrent();m.useClient(m.control,m.picker.control);assertEquals(original,m.source)}
    @Test fun reviewBackModeSwitchAndLocalResetKeepCandidateQueryAndDoNotClearServerRelation()=check {m,_,r->select(m,r);val selected=m.draft;m.prepare(m.control);m.back(m.control);assertEquals(selected,m.draft);m.choose(TaskClientEditMode.CLEAR,m.control);m.prepare(m.control);assertTrue(JSONObject(m.review!!.change!!.body()!!).isNull("client"));m.back(m.control);m.choose(TaskClientEditMode.SET,m.control);assertEquals(selected,m.draft);m.askClear(m.control);val old=m.clearConfirmation!!;m.dismissClear(old);m.choose(TaskClientEditMode.CLEAR,m.control);m.confirmClear(old);assertEquals(TaskClientEditMode.CLEAR,m.draft.mode);m.askClear(m.control);m.confirmClear(m.clearConfirmation!!);assertEquals(TaskClientEditDraft(),m.draft);assertEquals(source(),m.source)}
    @Test fun changedTaskReadRequiresReselectWhileRawCandidateRemainsUnsentInput()=check {m,_,r->select(m,r);val selected=m.draft;m.bind(source(revision=2));m.open(m.control);m.prepare(m.control);assertNull(m.review);assertEquals(selected,m.draft);assertEquals(selected.query,m.picker.state.query);assertFalse(m.picker.state.loaded);assertTrue(m.showsIssue)}
    @Test fun unknownKeepsOriginalModeCandidateQueryBodyAttemptAndCannotRekeyOnMatchingReread()=check {m,p,r->select(m,r);m.prepare(m.control);val review=m.review!!;val control=m.control;m.launchSubmit(control);runCurrent();val a=p.calls.single();val body=a.preparedBody();m.choose(TaskClientEditMode.CLEAR,m.control);m.askClear(m.control);m.launchSubmit(m.control);runCurrent();assertEquals(1,p.calls.size);assertEquals(review.draft,m.draft);p.pending.single().completeExceptionally(ReadException(ReadProblem.UNAVAILABLE));runCurrent();assertEquals(TaskClientEditPhase.UNKNOWN,m.submission!!.phase);m.bind(source(revision=2,original=TaskClientOriginal.Client(1754)));assertTrue(m.blocked);assertEquals(body,m.submission!!.attempt.preparedBody());assertEquals(review,m.submission!!.attempt.review);m.bind(source(revision=3,epoch=2));assertTrue(m.blocked);assertNull(m.submission);assertFalse(m.canOpen);assertEquals(1,m.retainedAttemptCount)}
    @Test fun unknownTaskDoesNotBlockIndependentBusinessAndUnknownOriginalDoesNotGrantNullEdit()=check {m,p,_->m.open(m.control);m.choose(TaskClientEditMode.CLEAR,m.control);m.prepare(m.control);m.launchSubmit(m.control);runCurrent();p.pending.single().complete(SyntheticTaskClientEditOutcome.Unknown);runCurrent();val other=detail(202,1201);m.bind(TaskClientEditSource(TaskCommentRead(TaskCommentContext(202,1201,2),2),other.task,other.clientRead));assertTrue(m.canOpen);assertFalse(m.blocked);m.bind(source(revision=2,original=TaskClientOriginal.Unknown));assertFalse(m.canOpen)}
    @Test fun fakeClearConfirmsSeparatelyConsumesOnlyThisReadAndNeverOptimisticallyChangesGet()=runTest {val original=source();val m=TaskClientEditModel(FixtureTaskClientEditPort(fixture("task-client-partial-outcome")),this,Repo());m.bind(original);m.open(m.control);m.choose(TaskClientEditMode.CLEAR,m.control);m.prepare(m.control);m.submit(m.control);val record=m.submission!!;assertEquals(TaskClientEditPhase.CONFIRMED,record.phase);assertNull(record.result!!.value);assertEquals(original,m.source);m.acknowledge(m.control,record);assertTrue(m.consumed);assertFalse(m.canOpen);assertEquals(original,m.source);m.bind(null)}
    @Test fun defaultOwnerAndGetOnlyOrMissingIndependentReadPortCannotCreateUpdateEditor()=runTest {Dispatchers.setMain(StandardTestDispatcher(testScheduler));val repo=Repo();val origin=object:TaskCommentDraftSource {override suspend fun matchesFixture(detail:TaskDetails)=detail==this@TaskClientEditTest.detail()};val plain=TaskListViewModel(repo,commentSource=origin);val noRead=TaskListViewModel(repo,commentSource=origin,clientEditSubmission=Port());try {plain.load(101,1);noRead.load(101,1);runCurrent();plain.open(1101);noRead.open(1101);runCurrent();assertNull(plain.clientEdit);assertNull(noRead.clientEdit);val noGrant=TaskClientEditModel(Port(false),this,repo);noGrant.bind(source());assertFalse(noGrant.canPresent)}finally {plain.viewModelScope.cancel();noRead.viewModelScope.cancel();Dispatchers.resetMain()}}
    @Test fun taskListLaneAndRawCommentCannotBypassUnknownRelationWriteAcrossEpoch()=runTest {Dispatchers.setMain(StandardTestDispatcher(testScheduler));val repo=Repo();val p=Port();val origin=object:TaskCommentDraftSource {override suspend fun matchesFixture(detail:TaskDetails)=detail==this@TaskClientEditTest.detail()};val m=TaskListViewModel(repo,commentSource=origin,dateEditSubmission=FixtureTaskDateEditPort(fixture("task-date-partial-outcome")),titleEditSubmission=FixtureTaskTitleEditPort(fixture("task-title-partial-outcome")),clientEditSubmission=p,clientEditReads=repo);try {m.load(101,1);runCurrent();m.open(1101);runCurrent();val a=m.clientEdit!!;val parent=m.control;m.openClientEdit(a.control,parent);m.openDateEdit(m.dateEdit!!.control,parent);assertTrue(a.editing);assertFalse(m.dateEdit.editing);assertFalse(m.dateEditCurrent(parent));a.choose(TaskClientEditMode.CLEAR,a.control);a.prepare(a.control);a.launchSubmit(a.control);runCurrent();p.pending.single().completeExceptionally(ReadException(ReadProblem.UNAVAILABLE));runCurrent();val state=m.state;assertTrue(m.taskActionOccupied);assertFalse(m.titleEditCurrent(m.control));m.comment?.state?.read?.let {m.openComment(it)};assertNull(m.comment?.state?.selection);assertEquals(state,m.state);m.load(101,2);runCurrent();m.open(1101);runCurrent();assertTrue(m.taskActionOccupied);assertFalse(m.hasHiddenRetainedAction);assertTrue(a.canPresent);assertTrue(a.blocked);assertTrue(m.clientEditCurrent(m.control));assertFalse(m.dateEditCurrent(m.control));assertFalse(m.titleEditCurrent(m.control));assertNull(a.submission);assertEquals(1,a.retainedAttemptCount)}finally {m.viewModelScope.cancel();Dispatchers.resetMain()}}
    @Test fun lateSourceBusinessChangeRejectsOldChoiceAndInputCallbacks()=check {m,_,r->list(m,r);m.openClient(1754,m.control,m.picker.control);runCurrent();val control=m.control;val child=m.picker.control;val input=m.inputControl;val other=detail(202,1201);m.bind(TaskClientEditSource(TaskCommentRead(TaskCommentContext(202,1201,2),2),other.task,other.clientRead));r.details.last().complete(profile());runCurrent();m.useClient(control,child);m.updateQuery("  ",input);assertNull(m.draft.choice);assertTrue(m.draft.query.isEmpty());assertEquals(202,m.source!!.read.context.business)}
    @Test fun parentQueryInputSurvivesConsecutiveEventsButNotReadModeOrTaskSource()=check {m,_,r->
        m.open(m.control);m.choose(TaskClientEditMode.SET,m.control);val input=m.inputControl!!;val read=m.picker.control
        for(raw in listOf(" ","  ","   ")){m.updateQuery(raw,input);assertEquals(raw,m.draft.query);assertEquals(input,m.inputControl)}
        m.readClients(m.control,read);runCurrent();assertTrue(r.lists.isEmpty());m.readClients(m.control,m.picker.control);runCurrent();m.updateQuery("overwrite",input);assertNull(m.inputControl);assertEquals("   ",m.draft.query)
        r.lists.single().complete(page());runCurrent();m.updateQuery("overwrite",input);assertEquals("   ",m.draft.query);assertNotEquals(input,m.inputControl)
        val mode=m.inputControl!!;m.choose(TaskClientEditMode.CLEAR,m.control);m.choose(TaskClientEditMode.SET,m.control);m.updateQuery("overwrite",mode);assertEquals("   ",m.draft.query);assertNotEquals(mode,m.inputControl)
        val source=m.inputControl!!;val old=m.source!!;m.bind(old.copy(read=old.read.copy(revision=2)));m.open(m.control);m.choose(TaskClientEditMode.SET,m.control);m.updateQuery("overwrite",source);assertEquals("   ",m.draft.query);assertNull(m.draft.choiceRead);assertNotEquals(source,m.inputControl)
    }
    @Test fun sharedRawUnicodeInputInPartialClientEditorRetainsQueryWithoutReadingOrInferringChoice()=check {m,_,r->
        m.open(m.control);m.choose(TaskClientEditMode.SET,m.control);val input=m.inputControl!!;val original=m.source;val rows=JSONObject(fixture("client-search-raw-unicode-cases")).getJSONArray("cases")
        for(i in 0 until rows.length()){val row=rows.getJSONObject(i);m.updateQuery(row.getString("before"),input);m.updateQuery(row.getString("after"),input);assertEquals(row.getString("after"),m.draft.query);assertEquals(row.getString("after"),m.picker.state.query);assertEquals(input,m.inputControl);assertEquals(original,m.source);assertNull(m.draft.choice);assertNull(m.draft.choiceRead);assertTrue(r.lists.isEmpty());assertTrue(r.details.isEmpty())}
    }
}
